mapper.select:
SELECT uid, phone, username, avatar, gender, college, major
FROM user
WHERE is_deleted = 0
  AND status = 1
  AND uid != #{currentUid}
  AND (
    uid = #{keyword}
    OR phone = #{keyword}
    OR username LIKE CONCAT('%', #{keyword}, '%')
  )
ORDER BY created_at DESC
LIMIT 20

mapper.update:
UPDATE user_friend
SET status = 1
WHERE id = #{id}
  AND friend_uid = #{friendUid}
  AND status = 0
